"use client"

import { Dialog as CommandDialogPrimitive } from "@base-ui/react/dialog"
import { SearchIcon } from "lucide-react"
import type * as React from "react"
import "@/styles/selection.styles.css"

import { cn } from "@/lib/utils"
import {
  Autocomplete,
  AutocompleteCollection,
  AutocompleteEmpty,
  AutocompleteGroup,
  AutocompleteGroupLabel,
  AutocompleteInput,
  AutocompleteItem,
  AutocompleteList,
  AutocompleteSeparator,
} from "@/components/ui/autocomplete"

export const CommandDialog: typeof CommandDialogPrimitive.Root = CommandDialogPrimitive.Root

export const CommandDialogPortal: typeof CommandDialogPrimitive.Portal =
  CommandDialogPrimitive.Portal

export const CommandCreateHandle: typeof CommandDialogPrimitive.createHandle =
  CommandDialogPrimitive.createHandle

export function CommandDialogTrigger(
  props: CommandDialogPrimitive.Trigger.Props
): React.ReactElement {
  return <CommandDialogPrimitive.Trigger data-slot="command-dialog-trigger" {...props} />
}

export function CommandDialogBackdrop({
  className,
  ...props
}: CommandDialogPrimitive.Backdrop.Props): React.ReactElement {
  return (
    <CommandDialogPrimitive.Backdrop
      className={cn(
        "fixed inset-0 z-50 bg-black/32 backdrop-blur-sm transition-all duration-200 data-ending-style:opacity-0 data-starting-style:opacity-0",
        className
      )}
      data-slot="command-dialog-backdrop"
      {...props}
    />
  )
}

export function CommandDialogViewport({
  className,
  ...props
}: CommandDialogPrimitive.Viewport.Props): React.ReactElement {
  return (
    <CommandDialogPrimitive.Viewport
      className={cn(
        "fixed inset-0 z-50 flex flex-col items-center px-4 py-[max(--spacing(4),4vh)] sm:py-[10vh]",
        className
      )}
      data-slot="command-dialog-viewport"
      {...props}
    />
  )
}

export function CommandDialogPopup({
  className,
  children,
  portalProps,
  ...props
}: CommandDialogPrimitive.Popup.Props & {
  portalProps?: CommandDialogPrimitive.Portal.Props
}): React.ReactElement {
  return (
    <CommandDialogPortal {...portalProps}>
      <CommandDialogBackdrop />
      <CommandDialogViewport>
        <CommandDialogPrimitive.Popup
          className={cn(
            "relative row-start-2 flex max-h-105 min-h-0 w-full min-w-0 max-w-xl -translate-y-[calc(1.25rem*var(--nested-dialogs))] scale-[calc(1-0.1*var(--nested-dialogs))] flex-col rounded-2xl border bg-popover not-dark:bg-clip-padding text-popover-foreground opacity-[calc(1-0.1*var(--nested-dialogs))] shadow-lg/5 outline-none transition-[scale,opacity,translate] duration-200 ease-in-out will-change-transform before:pointer-events-none before:absolute before:inset-0 before:rounded-[calc(var(--radius-2xl)-1px)] before:bg-muted/72 before:shadow-[0_1px_--theme(--color-black/4%)] data-nested:data-ending-style:translate-y-8 data-nested:data-starting-style:translate-y-8 data-nested-dialog-open:origin-top data-ending-style:scale-98 data-starting-style:scale-98 data-ending-style:opacity-0 data-starting-style:opacity-0 **:data-[slot=scroll-area-viewport]:data-has-overflow-y:pe-1 dark:before:shadow-[0_-1px_--theme(--color-white/6%)]",
            className
          )}
          data-slot="command-dialog-popup"
          {...props}
        >
          {children}
        </CommandDialogPrimitive.Popup>
      </CommandDialogViewport>
    </CommandDialogPortal>
  )
}

export function Command({
  autoHighlight = "always",
  keepHighlight = true,
  ...props
}: React.ComponentProps<typeof Autocomplete>): React.ReactElement {
  return (
    <Autocomplete
      autoHighlight={autoHighlight}
      inline
      keepHighlight={keepHighlight}
      open
      {...props}
    />
  )
}

export function CommandInput({
  className,
  placeholder = undefined,
  ...props
}: React.ComponentProps<typeof AutocompleteInput>): React.ReactElement {
  return (
    <div className="cn-command-input">
      <AutocompleteInput
        autoFocus
        className={cn("cn-command-input-field", className)}
        placeholder={placeholder}
        size="lg"
        startAddon={<SearchIcon />}
        {...props}
      />
    </div>
  )
}

export function CommandList({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteList>): React.ReactElement {
  return (
    <AutocompleteList
      className={cn("cn-command-list", className)}
      data-slot="command-list"
      {...props}
    />
  )
}

export function CommandEmpty({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteEmpty>): React.ReactElement {
  return (
    <AutocompleteEmpty
      className={cn("cn-command-empty", className)}
      data-slot="command-empty"
      {...props}
    />
  )
}

export function CommandPanel({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return (
    <div
      className={cn(
        "relative -mx-px not-has-[+[data-slot=command-footer]]:-mb-px min-h-0 rounded-t-xl not-has-[+[data-slot=command-footer]]:rounded-b-2xl border border-b-0 bg-popover bg-clip-padding shadow-xs/5 [clip-path:inset(0_1px)] not-has-[+[data-slot=command-footer]]:[clip-path:inset(0_1px_1px_1px_round_0_0_calc(var(--radius-2xl)-1px)_calc(var(--radius-2xl)-1px))] before:pointer-events-none before:absolute before:inset-0 before:rounded-t-[calc(var(--radius-xl)-1px)] **:data-[slot=scroll-area-scrollbar]:mt-2",
        className
      )}
      {...props}
    />
  )
}

export function CommandGroup({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteGroup>): React.ReactElement {
  return <AutocompleteGroup className={className} data-slot="command-group" {...props} />
}

export function CommandGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteGroupLabel>): React.ReactElement {
  return <AutocompleteGroupLabel className={className} data-slot="command-group-label" {...props} />
}

export function CommandCollection({
  ...props
}: React.ComponentProps<typeof AutocompleteCollection>): React.ReactElement {
  return <AutocompleteCollection data-slot="command-collection" {...props} />
}

export function CommandItem({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteItem>): React.ReactElement {
  return (
    <AutocompleteItem
      className={cn("cn-command-item", className)}
      data-slot="command-item"
      {...props}
    />
  )
}

export function CommandSeparator({
  className,
  ...props
}: React.ComponentProps<typeof AutocompleteSeparator>): React.ReactElement {
  return (
    <AutocompleteSeparator
      className={cn("cn-command-separator", className)}
      data-slot="command-separator"
      {...props}
    />
  )
}

export function CommandShortcut({
  className,
  ...props
}: React.ComponentProps<"kbd">): React.ReactElement {
  return (
    <kbd className={cn("cn-selection-meta", className)} data-slot="command-shortcut" {...props} />
  )
}

export function CommandFooter({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return (
    <div
      className={cn(
        "flex items-center justify-between gap-2 rounded-b-[calc(var(--radius-2xl)-1px)] border-t px-5 py-3 text-muted-foreground text-xs",
        className
      )}
      data-slot="command-footer"
      {...props}
    />
  )
}

export { CommandDialogPrimitive }

/* Selection/search anatomy. Public theme roles remain owned by the V2 foundation. */
@layer components {
  .cn-select-trigger {
    --selection-height: 36;
    --selection-inset: 12;
    --selection-type: 14;
    --selection-leading: 20;
    display: inline-flex;
    box-sizing: border-box;
    align-items: center;
    justify-content: space-between;
    gap: calc(6 * var(--cn-unit));
    width: fit-content;
    max-width: 100%;
    min-width: 0;
    height: calc(var(--selection-height) * var(--cn-unit));
    padding: 0 calc(var(--selection-inset) * var(--cn-unit) - 1px);
    border: 1px solid var(--cn-border-control);
    border-radius: var(--cn-radius-control);
    background: var(--cn-surface);
    color: var(--cn-text);
    font-size: calc(var(--selection-type) * var(--cn-unit));
    line-height: calc(var(--selection-leading) * var(--cn-unit));
    font-weight: 500;
    text-align: start;
    transition:
      border-color var(--cn-duration-fast) var(--cn-ease-standard),
      background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-select-trigger[data-size="sm"] {
    --selection-height: 32;
    --selection-inset: 10;
    --selection-type: 13;
    --selection-leading: 18;
  }
  .cn-select-trigger[data-size="lg"] {
    --selection-height: 40;
    --selection-inset: 14;
  }
  .cn-select-value {
    display: flex;
    flex: 1;
    align-items: center;
    gap: calc(6 * var(--cn-unit));
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    text-align: start;
  }
  .cn-select-trigger[data-placeholder] {
    color: var(--cn-text-muted);
    font-weight: 400;
  }
  .cn-select-icon {
    flex-shrink: 0;
    color: var(--cn-text-muted);
  }
  .cn-select-trigger svg,
  .cn-combobox-trigger svg,
  .cn-selection-start svg,
  .cn-selection-item :where(svg:not([class*="size-"])) {
    flex-shrink: 0;
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    pointer-events: none;
  }
  .cn-select-trigger[data-popup-open],
  :is(.cn-autocomplete-control, .cn-combobox-control):has(input[data-popup-open]),
  .cn-combobox-chips:has(input[data-popup-open]) {
    border-color: var(--cn-border-active);
  }
  .cn-select-trigger:is([aria-invalid="true"], [data-invalid]) {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-select-trigger[data-readonly] {
    background: var(--cn-surface-muted);
  }
  .cn-select-trigger:is(:disabled, [data-disabled]) {
    color: var(--cn-text-disabled);
    background: var(--cn-surface-disabled);
    border-color: var(--cn-border-disabled);
    cursor: not-allowed;
  }
  .cn-select-trigger:is(:disabled, [data-disabled]) .cn-select-icon {
    color: inherit;
  }
  .cn-select-trigger:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-selection-positioner {
    isolation: isolate;
    z-index: 50;
  }
  .cn-selection-popup {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: min(calc(144 * var(--cn-unit)), var(--available-width));
    width: var(--anchor-width);
    max-width: var(--available-width);
    max-height: min(var(--available-height), calc(368 * var(--cn-unit)));
    overflow: hidden;
    border: 1px solid var(--cn-border);
    border-radius: var(--cn-radius-card);
    background: var(--cn-surface-popup);
    color: var(--cn-text);
    box-shadow: var(--cn-shadow-popup);
    transform-origin: var(--transform-origin);
    transition:
      opacity var(--cn-duration-popup) var(--cn-ease-enter),
      scale var(--cn-duration-popup) var(--cn-ease-enter);
  }
  .cn-selection-popup:is([data-starting-style], [data-ending-style]) {
    opacity: 0;
    scale: 0.98;
  }
  .cn-selection-popup[data-ending-style] {
    transition-duration: var(--cn-duration-fast);
    transition-timing-function: var(--cn-ease-exit);
  }
  /* Item-aligned Select positioning measures the popup; do not scale that geometry. */
  .cn-select-popup[data-align-trigger="true"] {
    scale: none;
    transition: opacity var(--cn-duration-fast);
  }
  .cn-select-popup {
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .cn-selection-list {
    box-sizing: border-box;
    min-height: 0;
    padding: calc(4 * var(--cn-unit));
    scroll-padding-block: calc(4 * var(--cn-unit));
    outline: none;
  }
  .cn-selection-scroll {
    display: flex;
    flex-direction: column;
    max-height: inherit;
    flex: 1;
    min-height: 0;
    width: 100%;
    overflow: hidden;
  }
  .cn-selection-scroll > [data-slot="scroll-area-viewport"] {
    flex: 1;
    min-height: 0;
    max-height: inherit;
  }
  .cn-combobox-list {
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .cn-combobox-popup > .cn-input-group {
    margin: calc(4 * var(--cn-unit));
    flex-shrink: 0;
  }
  .cn-selection-item {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: calc(8 * var(--cn-unit));
    min-width: 0;
    min-height: calc(32 * var(--cn-unit));
    width: 100%;
    padding: calc(6 * var(--cn-unit)) calc(8 * var(--cn-unit));
    border-radius: var(--cn-radius-item);
    color: var(--cn-text);
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    font-weight: 400;
    overflow-wrap: anywhere;
    cursor: default;
    user-select: none;
    outline: none;
  }
  .cn-selection-text {
    display: flex;
    flex: 1;
    align-items: center;
    gap: calc(8 * var(--cn-unit));
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .cn-selection-indicator {
    display: flex;
    flex: 0 0 calc(16 * var(--cn-unit));
    align-self: center;
    align-items: center;
    justify-content: center;
    margin-inline-start: auto;
  }
  .cn-selection-indicator svg {
    width: calc(12 * var(--cn-unit));
    height: calc(12 * var(--cn-unit));
  }
  [data-check-position="left"] > .cn-selection-indicator {
    order: -1;
    margin-inline-start: 0;
  }
  .cn-selection-item[data-selected] {
    background: var(--cn-surface-selected);
    font-weight: 500;
  }
  .cn-selection-item[data-highlighted] {
    background: var(--cn-surface-hover);
  }
  /* Selection keeps its check; the inset edge marks navigation even on a selected row. */
  .cn-selection-item[data-highlighted] {
    box-shadow: inset calc(2 * var(--cn-unit)) 0 var(--cn-border-active);
  }
  .cn-selection-item[data-selected][data-highlighted] {
    background: var(--cn-surface-selected);
  }
  .cn-selection-item[data-disabled] {
    color: var(--cn-text-disabled);
    pointer-events: none;
  }
  .cn-selection-item[data-disabled][data-selected] {
    background: var(--cn-surface-disabled);
  }
  .cn-selection-group + .cn-selection-group {
    margin-block-start: calc(4 * var(--cn-unit));
  }
  .cn-selection-label {
    padding: calc(8 * var(--cn-unit));
    color: var(--cn-text-muted);
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 500;
  }
  .cn-selection-meta {
    flex-shrink: 0;
    margin-inline-start: auto;
    color: var(--cn-text-muted);
    font-family: inherit;
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 400;
  }
  .cn-selection-separator {
    height: 1px;
    margin: calc(4 * var(--cn-unit));
    background: var(--cn-border-subtle);
    pointer-events: none;
  }
  .cn-selection-empty,
  .cn-selection-status {
    padding: calc(12 * var(--cn-unit));
    color: var(--cn-text-muted);
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    overflow-wrap: anywhere;
  }
  .cn-selection-empty {
    text-align: center;
  }
  .cn-selection-empty:empty,
  .cn-selection-status:empty {
    margin: 0;
    padding: 0;
  }
  .cn-selection-status {
    flex-shrink: 0;
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
  }
  .cn-select-scroll {
    position: sticky;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: calc(24 * var(--cn-unit));
    width: 100%;
    background: var(--cn-surface-popup);
  }
  .cn-select-scroll-up {
    top: 0;
  }
  .cn-select-scroll-down {
    bottom: 0;
  }
  .cn-select-scroll svg {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
  }
  .cn-selection-start {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    padding-inline-start: calc(11 * var(--cn-unit));
    color: var(--cn-text-muted);
    pointer-events: none;
  }
  .cn-autocomplete-control:has(.cn-selection-start) .cn-input {
    padding-inline-start: calc(6 * var(--cn-unit));
  }
  .cn-selection-action {
    box-sizing: border-box;
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: calc(28 * var(--cn-unit));
    height: calc(28 * var(--cn-unit));
    padding: 0;
    border: 0;
    border-radius: var(--cn-radius-item);
    background: transparent;
    color: var(--cn-text-muted);
    cursor: pointer;
  }
  .cn-selection-action svg {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    pointer-events: none;
  }
  /* Inset contours stay complete inside compact composite boundaries. */
  .cn-selection-action:focus-visible,
  .cn-combobox-chip:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: -2px;
  }
  .cn-selection-action:is(:disabled, [data-disabled], [aria-disabled="true"]) {
    color: var(--cn-text-disabled);
    cursor: default;
  }
  .cn-autocomplete-control > .cn-selection-action {
    margin-inline-end: calc(3 * var(--cn-unit));
  }
  .cn-autocomplete-control:has([data-slot="autocomplete-clear"])
    > [data-slot="autocomplete-trigger"] {
    display: none;
  }
  .cn-combobox-clear:not([data-visible]):not(.cn-selection-query-clear) {
    display: none;
  }
  .cn-combobox-control:has(.cn-combobox-clear:is([data-visible], .cn-selection-query-clear))
    .cn-combobox-trigger {
    display: none;
  }
  :is(.cn-autocomplete-control, .cn-combobox-control):has(input[readonly]) .cn-selection-action {
    color: var(--cn-text-disabled);
  }
  .cn-combobox-chips {
    --chips-height: 36;
    --chip-height: 28;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: calc(4 * var(--cn-unit));
    width: 100%;
    min-width: 0;
    min-height: calc(var(--chips-height) * var(--cn-unit));
    padding: calc(3 * var(--cn-unit));
    border: 1px solid var(--cn-border-control);
    border-radius: var(--cn-radius-control);
    background: var(--cn-surface);
    color: var(--cn-text);
  }
  .cn-combobox-chips:has([data-size="sm"]) {
    --chips-height: 32;
    --chip-height: 24;
  }
  .cn-combobox-chips:has([data-size="lg"]) {
    --chips-height: 40;
  }
  .cn-combobox-chips:has(input:focus-visible) {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-combobox-chips:has(input[readonly]) {
    background: var(--cn-surface-muted);
  }
  :is(.cn-autocomplete-control, .cn-combobox-control, .cn-combobox-chips):has(
    input:is([aria-invalid="true"], [data-invalid])
  ) {
    border-color: var(--cn-status-destructive-border);
  }
  :is(.cn-autocomplete-control, .cn-combobox-control, .cn-combobox-chips):has(input:disabled) {
    color: var(--cn-text-disabled);
    border-color: var(--cn-border-disabled);
    background: var(--cn-surface-disabled);
  }
  .cn-combobox-chip {
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    min-width: 0;
    min-height: calc(var(--chip-height) * var(--cn-unit));
    padding-inline-start: calc(8 * var(--cn-unit));
    border-radius: var(--cn-radius-item);
    background: var(--cn-surface-selected);
    color: var(--cn-text);
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 500;
  }
  .cn-combobox-chip-text {
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .cn-combobox-chip-remove {
    align-self: stretch;
    height: auto;
    min-height: calc(var(--chip-height) * var(--cn-unit));
    margin-inline-start: calc(4 * var(--cn-unit));
  }
  .cn-combobox-chip[data-disabled] {
    color: var(--cn-text-disabled);
    background: var(--cn-surface-disabled);
  }
  .cn-combobox-chips-input {
    flex: 1;
    box-sizing: border-box;
    min-width: calc(64 * var(--cn-unit));
    width: 0;
    height: calc(var(--chips-height) * var(--cn-unit) - 8 * var(--cn-unit));
    padding-inline: calc(8 * var(--cn-unit));
    border: 0;
    background: transparent;
    color: inherit;
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    outline: none;
  }
  .cn-combobox-chips-input::placeholder {
    color: var(--cn-text-muted);
    opacity: 1;
  }
  .cn-command-input {
    padding: calc(8 * var(--cn-unit));
  }
  .cn-command-list {
    max-height: calc(320 * var(--cn-unit));
  }
  .cn-command-empty:not(:empty) {
    padding-block: calc(24 * var(--cn-unit));
  }
}
@media (hover: hover) {
  @layer components {
    .cn-select-trigger:not(
        :disabled,
        [data-disabled],
        [aria-invalid="true"],
        [data-invalid],
        [data-popup-open]
      ):hover {
      border-color: var(--cn-border-hover);
    }
    .cn-selection-item:not([data-disabled], [data-selected]):hover {
      background: var(--cn-surface-hover);
    }
    .cn-selection-action:not(:disabled, [data-disabled], [aria-disabled="true"]):hover {
      background: var(--cn-surface-hover);
      color: var(--cn-text);
    }
  }
}
@media (max-width: 40rem), (pointer: coarse) {
  @layer components {
    .cn-combobox-chips-input {
      font-size: calc(16 * var(--cn-unit));
      line-height: calc(24 * var(--cn-unit));
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    .cn-select-trigger {
      height: max(calc(var(--selection-height) * var(--cn-unit)), 44px);
    }
    .cn-selection-item {
      min-height: 44px;
    }
    .cn-selection-action {
      min-width: 44px;
      min-height: 44px;
    }
    .cn-autocomplete-control:has(.cn-selection-action),
    .cn-combobox-control:has(.cn-selection-action) {
      min-height: 52px;
    }
    .cn-combobox-chip {
      min-height: 44px;
    }
    .cn-combobox-chips {
      gap: calc(8 * var(--cn-unit));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .cn-select-trigger,
  .cn-selection-popup {
    transition: none;
    scale: none;
  }
}
@media (forced-colors: active) {
  .cn-select-trigger:focus-visible,
  .cn-selection-action:focus-visible,
  .cn-combobox-chip:focus-visible,
  .cn-combobox-chips:has(input:focus-visible) {
    outline-color: Highlight;
  }
  .cn-selection-item[data-highlighted] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
  .cn-selection-item[data-selected] {
    border-inline-start: 2px solid CanvasText;
  }
}
